/* Download Center (#/download-center): one card per Level module, files generated by pipeline/build_downloads.py.
   The list comes from downloads/modules/manifest.json, written by the same script. */
import { esc } from "./util.js";
import { levels } from "./content/levels.js";
import { diagramById } from "./content/diagrams.js";
import { crumbs, diagramFrame } from "./views.js";
import { bindTilt } from "./shell.js";

const BASE = "downloads/modules/";
let manifest = null;

export function moduleFor(id) {
  const l = levels.find((x) => x.module === id);
  return l ? { id, level: l.n, blurb: `Level ${l.n}, ${l.name}: ${l.blurb}` } : null;
}

const KIND = {
  pdf: { chip: "PDF", name: "Guide (PDF)", text: "Read it or print it. Every code example was run when the file was built, and its output is printed under the code." },
  docx: { chip: "DOCX", name: "Worksheet (Word)", text: "An editable copy for your own notes, class handouts or exercises." },
  pptx: { chip: "PPTX", name: "Slides (PowerPoint)", text: "Present it or study slide by slide. Green slides show the output of the code." },
  html: { chip: "HTML", name: "Guide (web page)", text: "The same guide as one web page. It opens offline in any browser." },
  png: { chip: "PNG", name: "Cover card (image)", text: "A poster-size image of the outcomes for this Level. Use it as a cover or a wallpaper." },
};
const ORDER = ["pdf", "docx", "pptx", "html", "png"];

function fileRow(f) {
  const k = KIND[f.format]; if (!k) return "";
  return `<li class="dc-file" data-format="${f.format}">
    <a class="dc-btn dc-${f.format}" href="${BASE}${esc(f.name)}" download aria-describedby="d-${esc(f.sha256.slice(0, 8))}"><span class="dc-chip">${k.chip}</span><span class="dc-name">${esc(k.name)}</span><span class="dc-size">${esc(f.size)}</span></a>
    <span class="dc-desc" id="d-${esc(f.sha256.slice(0, 8))}">${esc(k.text)} <span class="dc-fn">${esc(f.name)}</span></span></li>`;
}

function card(m) {
  const files = ORDER.map((fmt) => m.files.find((f) => f.format === fmt)).filter(Boolean);
  const cover = m.files.find((f) => f.format === "png");
  const lvl = levels.find((l) => l.n === m.level);
  return `<article class="dc-card" id="dc-${esc(m.id)}" data-tilt data-level="${m.level}" style="--acc:${esc(m.accent)}">
    <div class="dc-cover">${cover ? `<img src="${BASE}${esc(cover.name)}" alt="Cover card for ${esc(m.title)}: its outcomes on a ${esc(lvl ? lvl.name : "")} coloured poster" loading="lazy" width="640" height="360">` : ""}</div>
    <div class="dc-body">
      <p class="kicker"><span class="pill">Level ${m.level}</span><span class="pill">about ${m.hours} h</span><span class="pill">${esc(m.audience)}</span></p>
      <h2>${esc(m.title.replace(/^Level \d+: /, ""))}</h2>
      <p>${esc(m.blurb)} Project: ${esc(m.project)}.</p>
      <ul class="dc-files">${files.map(fileRow).join("")}</ul>
      <details><summary>What's inside</summary>
        <ul>${m.whats_inside.map((o) => `<li>${esc(o)}</li>`).join("")}</ul>
        <p><b>How to use:</b> ${esc(m.how_to_use.pdf)} ${esc(m.how_to_use.pptx)}</p>
        <p class="muted">Examples run on ${esc(m.examples_run_on)} (${m.snippets_executed} code blocks executed at build time; the page runtime is Pyodide, so output can differ in small ways). Licence: code ${esc(m.license.code)}, text ${esc(m.license.text)}. Not accredited coursework; no outcome is promised.</p>
        <details class="dc-sums"><summary>Checksums (SHA-256)</summary><ul>${files.map((f) => `<li><code>${esc(f.sha256)}</code> ${esc(f.name)}</li>`).join("")}</ul></details>
        <p><a class="text-btn" href="${BASE}${esc(m.base)}_description.json" download>Description file (JSON)</a> <a class="text-btn" href="${BASE}${esc(m.base)}_description.txt" download>Description (plain text)</a> <a class="text-btn" href="#/worlds/${m.level}">Open the Level ${m.level} world</a></p>
      </details>
    </div></article>`;
}

export function downloadCenterView(focus, extraHtml = "") {
  const arch = diagramById("lab-architecture");
  return {
    html: `${crumbs([{ href: "#/", label: "Home" }, { href: "#/downloads", label: "Downloads" }])}
      <h1>Downloads</h1>
      <p class="lede" data-speak>Take a Level with you. Each Level comes as a PDF guide, a Word worksheet, PowerPoint slides, an offline web page and a cover image, all built from one source so they always agree. Free, no account.</p>
      <div class="dc-tools" role="search">
        <label class="visually-hidden" for="dc-q">Filter the files</label>
        <input id="dc-q" type="search" placeholder="Filter by Level or topic" autocomplete="off">
        <div class="dc-fmts" role="group" aria-label="Show only this format">
          ${["all", ...ORDER].map((f) => `<button type="button" class="theme-btn" data-dcf="${f}" aria-pressed="${f === "all"}">${f === "all" ? "All" : KIND[f].chip}</button>`).join("")}
        </div>
      </div>
      <p class="muted" id="dc-status" role="status">Loading the file list.</p>
      <div class="dc-grid" id="dc-cards"></div>
      <p class="muted">Only Levels 0 to 3 have files so far. The Level 3 guide is the deepest sample. The cheat sheets, slides Markdown and notebook are further down this page.</p>
      ${extraHtml}
      <h2>How the level files are built</h2>
      <p>One Markdown source per Level goes through a script that runs every code block, then writes the PDF, Word, PowerPoint, HTML, image and description files. The map below was made with Archify. It shows the whole plan, so some boxes are not built yet.</p>
      ${arch ? diagramFrame(arch, 620) : ""}`,
    after() {
      const grid = document.getElementById("dc-cards");
      const status = document.getElementById("dc-status");
      const apply = () => {
        const q = document.getElementById("dc-q").value.trim().toLowerCase();
        const f = document.querySelector("[data-dcf][aria-pressed=true]")?.dataset.dcf || "all";
        let shown = 0;
        grid.querySelectorAll(".dc-card").forEach((c) => {
          const text = c.textContent.toLowerCase();
          const okQ = !q || q.split(/\s+/).every((w) => text.includes(w) || `level ${c.dataset.level}`.includes(w));
          const okF = f === "all" || !!c.querySelector(`.dc-file[data-format=${f}]`);
          c.hidden = !(okQ && okF);
          c.querySelectorAll(".dc-file").forEach((li) => { li.hidden = f !== "all" && li.dataset.format !== f; });
          if (!c.hidden) shown += 1;
        });
        status.textContent = shown ? `${shown} Level${shown === 1 ? "" : "s"} shown.` : "No Level matches that filter.";
      };
      document.getElementById("dc-q").addEventListener("input", apply);
      document.querySelectorAll("[data-dcf]").forEach((b) => b.addEventListener("click", () => {
        document.querySelectorAll("[data-dcf]").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
        apply();
      }));
      const draw = (data) => {
        grid.innerHTML = data.modules.sort((a, b) => a.level - b.level).map(card).join("");
        bindTilt(grid); apply();
        if (focus) { const el = document.getElementById(`dc-${focus}`); el?.scrollIntoView({ block: "center" }); el?.classList.add("is-focus"); }
      };
      (manifest ? Promise.resolve(manifest) : fetch(`${BASE}manifest.json`).then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); }))
        .then((d) => { manifest = d; draw(d); })
        .catch(() => { status.textContent = "The file list could not be loaded. Open the page again, or scroll down for the cheat sheets."; });
    },
  };
}
